import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"A2 Public Evidence Pack: Event Consumer Visibility","description":"","frontmatter":{"title":"A2 Public Evidence Pack: Event Consumer Visibility","date":"2026-08-28","updated":"2026-08-31","column":"research-evidence","category":"evidence","article_type":"evidence-pack","edition":"research-center","summary":"Preserves the 20,440-row historical event profile and V2.0.4 query probe, then adds the V2.1.2 three-consumer projection contract, first regression failure and independent-QA result.","lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"en/research/evidence/2026-08-28-event-consumer-visibility.md","filePath":"en/research/evidence/2026-08-28-event-consumer-visibility.md","lastUpdated":1788146003000}'),r={name:"en/research/evidence/2026-08-28-event-consumer-visibility.md"};function n(l,e,d,o,h,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<p><a href="/joinwell52/zh/research/evidence/2026-08-28-event-consumer-visibility">中文版本</a></p><h1 id="a2-event-consumer-visibility" tabindex="-1">A2 | Event Consumer Visibility <a class="header-anchor" href="#a2-event-consumer-visibility" aria-label="Permalink to &quot;A2 | Event Consumer Visibility&quot;">​</a></h1><h2 id="claim" tabindex="-1">Claim <a class="header-anchor" href="#claim" aria-label="Permalink to &quot;Claim&quot;">​</a></h2><p>Historical storage containing projected fields does not prove that every query and outbound consumer applies the same least-visibility contract. In the tested V2.0.4 Activity path, an ordinary query returned a unique marker that existed only inside <code>payload.raw</code>. That is an old-baseline result; the delivered V2.1.2 behavior is documented below.</p><h2 id="historical-data-profile" tabindex="-1">Historical data profile <a class="header-anchor" href="#historical-data-profile" aria-label="Permalink to &quot;Historical data profile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dataset</th><th style="text-align:right;">Rows</th><th style="text-align:right;">With <code>payload.raw</code></th><th style="text-align:right;">Share</th></tr></thead><tbody><tr><td>Runtime</td><td style="text-align:right;">2,743</td><td style="text-align:right;">1,474</td><td style="text-align:right;">53.7%</td></tr><tr><td>Analytics</td><td style="text-align:right;">17,697</td><td style="text-align:right;">16,828</td><td style="text-align:right;">95.1%</td></tr><tr><td>Total</td><td style="text-align:right;">20,440</td><td style="text-align:right;">18,302</td><td style="text-align:right;">89.5%</td></tr></tbody></table><p>A later Analytics subset from August 10 and 12 contained 681 rows with <code>payload.raw=0</code>. This is a sample observation, not a global field-allowlist guarantee.</p><h2 id="re-runnable-public-attachments" tabindex="-1">Re-runnable public attachments <a class="header-anchor" href="#re-runnable-public-attachments" aria-label="Permalink to &quot;Re-runnable public attachments&quot;">​</a></h2><p>The Reader/check below reads frozen JSON and verifies the statistics and probe record. It does not execute the private Runtime. The <code>current</code> field in the output refers to the original experiment baseline, not the version current when this page is read.</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A2-event-consumer-fixture.json">Sanitized fixture</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A2-event-consumer-reader.mjs">Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A2-event-consumer-check.mjs">Check script</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/MANIFEST.txt">Attachment SHA-256 manifest</a></li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node A2-event-consumer-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;evidence_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RBE-20260828-A2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rows&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20440</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rows_with_payload_raw&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18302</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;raw_percent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">89.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;runtime_raw_percent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">53.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;analytics_raw_percent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">95.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;current_query_returned_raw_marker&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><p>The historical overall share is not a current V2.0.4 share. Raw fields appearing in a query result do not by themselves prove unauthorized access occurred. The public fixture does not cover Panel, Webhook, LAN or every diagnostic entry point.</p><h2 id="_2026-08-30-v2-1-2-delivered-update" tabindex="-1">2026-08-30: V2.1.2 delivered update <a class="header-anchor" href="#_2026-08-30-v2-1-2-delivered-update" aria-label="Permalink to &quot;2026-08-30: V2.1.2 delivered update&quot;">​</a></h2><p>A pre-fix rerun on V2.1.1 <code>36e5c83b</code> confirmed that the raw marker could still be returned. V2.1.2 introduced server-defined <code>web_panel / activity_api / analytics</code> consumer policies and reconstructs new objects from recursive field allowlists. Unknown events do not pass unknown payloads through, while raw internal events remain available to authorized internal paths.</p><p>The first Shell targeted regression was 19 pass / 1 fail because semantic warning count dropped from 1 to 0 after an allowed diagnostic signal was over-pruned. After deriving and projecting only <code>ok/code/summary_blocked_reason/projection_status</code>, the targeted rerun reached 20/20 without restoring raw pass-through.</p><p>Independent QA B1 on candidate <code>64f633ac</code> observed one event, raw-marker count 0 and <code>raw_present=false</code>; event_type, task_id, session_id and projected_summary remained. B1 is an internal acceptance identifier, not this public A2 pack number.</p><h2 id="sources-for-the-newer-claims-and-review-visibility" tabindex="-1">Sources for the newer claims and review visibility <a class="header-anchor" href="#sources-for-the-newer-claims-and-review-visibility" aria-label="Permalink to &quot;Sources for the newer claims and review visibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim</th><th>First-party source</th><th>Visibility</th></tr></thead><tbody><tr><td>Pre-fix marker visibility and allowlist implementation</td><td><code>RUNTIME-BOUNDARY-20260830-001</code>, implementation <code>3302ca61</code></td><td>Restricted mother-repository material</td></tr><tr><td>Over-pruning regression and repair, 19/20 → 20/20</td><td>Failures and targeted-final records in the same pack</td><td>Restricted mother-repository material</td></tr><tr><td>B1 independent validation</td><td><code>RUNTIME-BOUNDARY-QA-20260830-001</code>: independent-qa records</td><td>Restricted mother-repository material</td></tr><tr><td>V2.1.2 release and final regression</td><td><code>V2.1.2-R3</code>, <code>V2.1.2-PUBLICATION-20260830-001</code>; Runtime 1842 pass / 0 fail / 1 skip, Shell 1037 pass / 0 fail</td><td>First-party release record, 2026-08-30</td></tr></tbody></table><p>The <a href="/joinwell52/en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">CodeFlowMu V2.1.2 Public Release Summary</a> consolidates recursive allowlisting, safe projection, B1 independent QA, compatibility, release gates and residual risk. Complete source and raw release material remain restricted first-party evidence and are not public reading links; the historical JSON is not presented as a public fixture that can fully rerun the new private product.</p><p>The three current consumer projections are not a universal sensitive-content detector, complete subscriber governance or a real-network authorization audit. Open Edition was not released and no online instance is implied to have switched. Existing dependency warnings, the symlink-permission skip and uncovered real LAN/Gateway scope remain explicit. The historical 681-row raw=0 sample also cannot substitute for the new implementation tests.</p>',23)])])}const k=t(r,[["render",n]]);export{u as __pageData,k as default};
